CREATE TABLE `workspaces` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`name` VARCHAR(120) NOT NULL,`slug` VARCHAR(63) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`status` ENUM('active','archived') NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_workspaces_org_slug`(`organization_id`,`slug`),KEY `idx_workspaces_org_status`(`organization_id`,`status`,`updated_at`),CONSTRAINT `fk_workspaces_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_workspaces_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
